static const char activeProtocolHead[] = {'<', '~'};
static const char activeProtocolTail[] =  {'~', '>'};
static const char activeProtocolEOF = '\n';

/** Functions ----------------------------------------------------------------*/
void Display_DataToProtocol(s_DisplayProtocolData* dataIn, uint8_t* bufferOut) {

	// Head
	memcpy(bufferOut + POS_HEAD, activeProtocolHead, 2);
	// Command
	memcpy(bufferOut + POS_COMMAND, &dataIn->Command, 2);
	// Data
	memcpy(bufferOut + POS_PARAM1, &dataIn->Param1, 4);
	memcpy(bufferOut + POS_PARAM2, &dataIn->Param2, 4);
	memcpy(bufferOut + POS_PARAM3, &dataIn->Param3, 4);
	memcpy(bufferOut + POS_DIGITS, dataIn->Digits, 8);
	// CRC (Command + Data)
	uint16_t calcCRC = CRC16_Modbus(bufferOut + POS_COMMAND, POS_CHECKSUM - POS_COMMAND);
	memcpy(bufferOut + POS_CHECKSUM, &calcCRC, 2);
	// Tail
	memcpy(bufferOut + POS_TAIL, activeProtocolTail, 2);
	// EOF
	memcpy(bufferOut + POS_EOF, &activeProtocolEOF, 1);
}

